import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'package:dio/dio.dart';
import 'package:google_generative_ai/google_generative_ai.dart';
import 'package:news_app_clean_architecture/features/firebase_articles/domain/entities/generated_article.dart';
import 'package:path_provider/path_provider.dart';

class AiArticleDataSource {
  final GenerativeModel _textModel;
  final Dio _dio;
  final String _apiKey;

  static const List<String> _textModels = [
    'gemini-2.5-flash',
    'gemini-2.0-flash',
    'gemini-2.5-flash-lite',
  ];

  static const List<String> _imageModels = [
    'gemini-2.5-flash-image',
    'gemini-2.0-flash-exp',
  ];

  AiArticleDataSource(String apiKey)
      : _apiKey = apiKey,
        _dio = Dio(),
        _textModel = GenerativeModel(
          model: _textModels.first,
          apiKey: apiKey,
          generationConfig: GenerationConfig(
            responseMimeType: 'application/json',
            responseSchema: Schema(
              SchemaType.object,
              requiredProperties: ['title', 'description', 'content'],
              properties: {
                'title': Schema(
                  SchemaType.string,
                  description:
                      'A compelling headline about the Symmetry app, max 100 characters',
                ),
                'description': Schema(
                  SchemaType.string,
                  description:
                      'A brief summary highlighting Symmetry features, max 200 characters',
                ),
                'content': Schema(
                  SchemaType.string,
                  description:
                      'Full article body, 3-5 well structured paragraphs focusing on Symmetry AI fitness',
                ),
              },
            ),
          ),
        );

  Future<GeneratedArticle> generateArticle(String prompt) async {
    for (int i = 0; i < _textModels.length; i++) {
      try {
        final model = GenerativeModel(
          model: _textModels[i],
          apiKey: _apiKey,
          generationConfig: GenerationConfig(
            responseMimeType: 'application/json',
            responseSchema: Schema(
              SchemaType.object,
              requiredProperties: ['title', 'description', 'content'],
              properties: {
                'title': Schema(
                  SchemaType.string,
                  description:
                      'A compelling headline about the Symmetry app, max 100 characters',
                ),
                'description': Schema(
                  SchemaType.string,
                  description:
                      'A brief summary highlighting Symmetry features, max 200 characters',
                ),
                'content': Schema(
                  SchemaType.string,
                  description:
                      'Full article body, 3-5 well structured paragraphs focusing on Symmetry AI fitness',
                ),
              },
            ),
          ),
        );

        final response = await model.generateContent([
          Content.text(
            'You are a tech and fitness product expert. Based on the following prompt, '
            'generate an article focused specifically on the "Symmetry: AI Gym Workout Log" app. '
            'Highlight its core features where relevant: the AI Body Scanner, Automatic Progressive Overload, '
            'and Gamification/Ranking system. Ensure the tone is engaging and professional. '
            'Always write in English regardless of the language of the prompt.\n\nPrompt: $prompt',
          ),
        ]);

        final text = response.text;
        if (text == null || text.isEmpty) continue;

        final Map<String, dynamic> json = jsonDecode(text);

        final title = json['title'];
        final description = json['description'];
        final content = json['content'];

        if (title == null || description == null || content == null) continue;

        return GeneratedArticle(
          title: title.toString(),
          description: description.toString(),
          content: content.toString(),
        );
      } catch (e) {
        if (i == _textModels.length - 1) rethrow;
      }
    }
    throw Exception('All text models failed');
  }

  Future<File> generateArticleImage(String articleTitle) async {
    // 1. Simulamos el tiempo de espera de la API (opcional, para que la UI se comporte natural)
    await Future.delayed(const Duration(seconds: 2));

    // 2. Aquí pegas tu string gigante de base64
    const String mockBase64Data =
        ""; // REEMPLAZA ESTO CON TU BASE64 REAL

    try {
      // 3. Decodificamos y guardamos el archivo tal cual querías
      final Uint8List bytes = base64Decode(mockBase64Data);

      final tempDir = await getTemporaryDirectory();
      final timestamp = DateTime.now().millisecondsSinceEpoch;

      // Asumimos jpg por defecto para el mock, cámbialo a png si tu base64 es de un PNG
      final file = File('${tempDir.path}/ai_thumbnail_mocked_$timestamp.jpg');
      await file.writeAsBytes(bytes);

      return file;
    } catch (e) {
      throw Exception('Mock image generation failed: $e');
    }
  }
}
